const s = String(args.expression ?? '').replace(/\s+/g, '');
if (!/^[0-9+*/().-]+$/.test(s)) throw new Error('only arithmetic is allowed');
let i = 0;
const num = () => { const start = i; while (/[0-9.]/.test(s[i] ?? '')) i++; if (start === i) throw new Error('bad expression'); return parseFloat(s.slice(start, i)); };
const factor = () => { if (s[i] === '-') { i++; return -factor(); } if (s[i] === '(') { i++; const v = expr(); if (s[i++] !== ')') throw new Error('missing )'); return v; } return num(); };
const term = () => { let v = factor(); while (s[i] === '*' || s[i] === '/') { const op = s[i++]; const r = factor(); v = op === '*' ? v * r : v / r; } return v; };
const expr = () => { let v = term(); while (s[i] === '+' || s[i] === '-') { const op = s[i++]; const r = term(); v = op === '+' ? v + r : v - r; } return v; };
const result = expr();
if (i !== s.length) throw new Error('bad expression');
return { result };
